//! The corpus below was generated by the Go implementation right before it was deleted
//! (`zz_sb_fixture_gen_test.go`, now gone). Each row is `raw -> normalized`, the digest set and
//! the query name, so the port is compared against real output rather than against a re-reading of
//! the old source.

use super::*;
use crate::engine::SAFE_BROWSING_SUFFIX;

const CORPUS: &str = include_str!("../../tests/fixtures/hash_corpus.tsv");

#[test]
fn fixture_matches_the_go_implementation() {
    let mut rows = 0usize;
    for line in CORPUS.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 4, "malformed fixture row {line:?}");
        let (raw, normalized, hashes, question) = (fields[0], fields[1], fields[2], fields[3]);

        match normalize_check_host(raw) {
            None => {
                assert_eq!(normalized, "", "raw {raw:?} should be rejected");
                assert_eq!(hashes, "", "raw {raw:?}");
                assert_eq!(question, "", "raw {raw:?}");
            }
            Some(host) => {
                assert_eq!(host, normalized, "normalized host of {raw:?}");
                if !normalized.is_ascii() {
                    // The `psl` crate also ships the Unicode forms of the suffixes; the Go PSL
                    // snapshot only carried punycode. Pinned separately below and in the README.
                    continue;
                }
                let computed = hostname_to_hashes(&host);
                let encoded: Vec<String> = computed.iter().map(|hash| hex_encode(hash)).collect();
                assert_eq!(encoded.join(","), hashes, "digests of {raw:?}");
                assert_eq!(
                    build_question_name(&computed, SAFE_BROWSING_SUFFIX),
                    question,
                    "question of {raw:?}"
                );
            }
        }
        rows += 1;
    }
    assert!(
        rows > 50,
        "fixture should cover the corpus, got {rows} rows"
    );
}

#[test]
fn degenerate_hosts_have_no_verdict() {
    for host in ["", "  ", ".", "..", "...", "a..b.com"] {
        assert_eq!(normalize_check_host(host), None, "host {host:?}");
    }
}

#[test]
fn normalization_lowercases_and_trims() {
    assert_eq!(
        normalize_check_host("  Example.COM.  ").as_deref(),
        Some("example.com")
    );
    assert_eq!(
        normalize_check_host("HOST.com...").as_deref(),
        Some("host.com")
    );
}

#[test]
fn unicode_host_is_lowercased_with_go_semantics() {
    // `strings.ToLower` maps U+0130 to a plain `i`; Rust's full mapping would add U+0307 and the
    // name would stop being a domain name.
    assert_eq!(
        normalize_check_host("A\u{0130}.com").as_deref(),
        Some("ai.com")
    );
}

#[test]
fn unicode_hosts_use_the_psl_crate_snapshot() {
    // Known boundary: `golang.org/x/net/publicsuffix` only lists punycode suffixes, so `рф` was an
    // unknown TLD and every label was hashed; the `psl` crate also lists the Unicode label, so it
    // anchors on it. DNS question names are already punycode, so the query path never sees this.
    assert!(hostname_to_hashes("пример.рф").len() == 1);
    assert_eq!(hostname_to_hashes("β.example.com").len(), 2);
}

#[test]
fn deep_names_are_truncated_to_four_labels() {
    let hashes = hostname_to_hashes("a.b.c.d.e.f.example.com");
    assert_eq!(hashes.len(), 3);
    let mut expected = [0u8; HASH_SIZE];
    expected.copy_from_slice(&digest("e.f.example.com"));
    assert!(hashes.contains(&expected));
}

#[test]
fn public_suffix_itself_is_not_hashed() {
    assert!(hostname_to_hashes("com").is_empty());
    assert!(hostname_to_hashes("co.uk").is_empty());
    assert_eq!(hostname_to_hashes("host.com").len(), 1);
}

#[test]
fn non_icann_suffix_walks_every_label() {
    // `dyndns.org` is a private suffix, so there is no registrable domain to anchor on.
    assert_eq!(hostname_to_hashes("foo.dyndns.org").len(), 3);
    assert_eq!(hostname_to_hashes("bar.foo.dyndns.org").len(), 4);
}

#[test]
fn escaped_labels_are_still_domain_names() {
    // miekg/dns accepts escaped bytes; the port keeps that instead of rejecting them.
    assert!(normalize_check_host("a\\.b.com").is_some());
    assert!(normalize_check_host("a\\046b.com").is_some());
    assert!(normalize_check_host("a\\").is_some());
    assert!(normalize_check_host("a b.com").is_some());
}

#[test]
fn txt_hashes_accept_both_cases_and_drop_the_rest() {
    let lower = "a379a6f6eeafb9a55e378c118034e2751e682fab9f2d30ab13d2125586ce1947";
    let upper = lower.to_uppercase();
    let short = "deadbeef";
    let non_hex = "z".repeat(HASH_HEX_SIZE);
    let parsed = parse_txt_hashes(&[lower, &upper, short, &non_hex]);
    assert_eq!(parsed.len(), 2);
    assert_eq!(hex_encode(&parsed[0]), lower);
    assert_eq!(parsed[0], parsed[1]);
}

#[test]
fn question_name_uses_two_byte_prefixes() {
    let hashes = hostname_to_hashes("sub.host.com");
    let name = build_question_name(&hashes, SAFE_BROWSING_SUFFIX);
    assert!(name.ends_with(SAFE_BROWSING_SUFFIX));
    let labels = name.trim_end_matches(SAFE_BROWSING_SUFFIX);
    let labels: Vec<&str> = labels
        .split('.')
        .filter(|label| !label.is_empty())
        .collect();
    assert_eq!(labels.len(), hashes.len());
    for label in labels {
        assert_eq!(label.len(), HASH_PREFIX_LEN * 2);
    }
}

#[test]
fn empty_digest_set_still_names_the_suffix() {
    assert_eq!(
        build_question_name(&[], SAFE_BROWSING_SUFFIX),
        SAFE_BROWSING_SUFFIX
    );
}
